/**
 * Flashcards del tema-1 (La Constitución Española) — una card por apartado
 * numerado de cada artículo (título completo, arts. 1 a 169 + disposiciones).
 * Fuente: content-raw/constitucion-espanola/*.md
 *
 * Uso: node --env-file=.env.local scripts/seed-flashcards-tema-1.mjs
 */

const URL_BASE = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!URL_BASE || !SERVICE_KEY) {
  console.error("❌ Faltan NEXT_PUBLIC_SUPABASE_URL o SUPABASE_SERVICE_ROLE_KEY.");
  process.exit(1);
}

const HEADERS = {
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  "Content-Type": "application/json",
};

async function insertBatch(filas) {
  const res = await fetch(`${URL_BASE}/rest/v1/flashcards`, {
    method: "POST",
    headers: { ...HEADERS, Prefer: "return=minimal" },
    body: JSON.stringify(filas),
  });
  if (!res.ok) {
    console.error(`❌ Error insertando: ${res.status} ${await res.text()}`);
    process.exit(1);
  }
}

